/*
# Marinduque municipality boundaries

1. Summary
- Adds a reference table with the outlines of the six Marinduque municipalities so the 3D globe can draw them.
- Seeds the six municipalities (Boac, Buenavista, Gasan, Mogpog, Santa Cruz, Torrijos).

2. New Tables
- `municipality_boundaries`
  - `id` (uuid, primary key)
  - `municipality` (text, unique, municipality name)
  - `province` (text, default 'Marinduque')
  - `geometry_data` (jsonb, GeoJSON MultiPolygon in longitude/latitude order)
  - `source` (text, where the outline came from)
  - `source_year` (integer, boundary dataset year)
  - `created_at` (timestamptz)

3. Security
- Row level security is enabled.
- Public reference data: anon and authenticated users can read it.
- No insert, update, or delete policies, so the data can only change through migrations.

4. Notes
- Outlines come from geoBoundaries (ADM3, open license, 2020 vintage), clipped to Marinduque and simplified to about 200 m accuracy.
- Boundaries are approximate and should be checked against official PSA or LGU maps before legal use.
*/

CREATE TABLE IF NOT EXISTS municipality_boundaries (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  municipality text NOT NULL UNIQUE,
  province text NOT NULL DEFAULT 'Marinduque',
  geometry_data jsonb NOT NULL,
  source text NOT NULL,
  source_year integer,
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE municipality_boundaries ENABLE ROW LEVEL SECURITY;

GRANT SELECT ON municipality_boundaries TO anon, authenticated;

DROP POLICY IF EXISTS "anon_select_municipality_boundaries" ON municipality_boundaries;
CREATE POLICY "anon_select_municipality_boundaries" ON municipality_boundaries
  FOR SELECT TO anon, authenticated USING (true);

