INSERT INTO municipality_boundaries (municipality, geometry_data, source, source_year)
SELECT
  s.value->>'name',
  jsonb_build_object(
    'type', 'MultiPolygon',
    'coordinates', (SELECT jsonb_agg(jsonb_build_array(ring)) FROM jsonb_array_elements(s.value->'polygons') AS ring)
  ),
  'geoBoundaries gbOpen ADM3 (wmgeolab), clipped and simplified',
  2020
FROM seed, jsonb_array_elements(seed.doc) AS s(value)
ON CONFLICT (municipality) DO NOTHING;
